    // p = [a, b, c]: y = a*exp(-b*x) + c.
    public struct ExpDecayResidual : IfloatResidualFunction
    {
        public floatN X, Y;
        public void Residuals(in floatN p, ref floatN r)
        {
            for (int i = 0; i < r.N; i++)
                r[i] = p[0] * math.exp(-p[1] * X[i]) + p[2] - Y[i];
        }
    }

    // Same model as ExpDecayResidual, with an analytic Jacobian (for the numeric-vs-analytic check).
    public struct ExpDecayJacobian : IfloatResidualJacobian
    {
        public floatN X, Y;
        public void Residuals(in floatN p, ref floatN r)
        {
            for (int i = 0; i < r.N; i++)
                r[i] = p[0] * math.exp(-p[1] * X[i]) + p[2] - Y[i];
        }
        public void Jacobian(in floatN p, ref floatMxN J)
        {
            for (int i = 0; i < J.M_Rows; i++)
            {
                float e = math.exp(-p[1] * X[i]);
                J[i, 0] = e;
                J[i, 1] = -p[0] * X[i] * e;
                J[i, 2] = (float)1;
            }
        }
    }

    // p = [A, w, phi, off]: y = A*sin(w*t + phi) + off.
    public struct SineResidual : IfloatResidualFunction
