            AssertSolved(info);
            AssertClose(p[0], (float)2, (float)0.01);
            AssertClose(p[1], (float)1, (float)0.01);

            arena.Dispose();
        }

        // Calls curveFit 30 times in a row on the same small dataset: exercises the internal
        // Allocator.Temp scratch's allocate/dispose cycle repeatedly (a leaked buffer would be
        // caught by Unity's collections checks well before iteration 30).
        void RepeatedCallsNoLeak()
        {
            var arena = new Arena(Allocator.Persistent);

            var xdata = arena.floatVec(5);
            var ydata = arena.floatVec(5);
            SetXY(xdata, ydata, 0, (float)0, (float)1.01); SetXY(xdata, ydata, 1, (float)1, (float)2.98);
            SetXY(xdata, ydata, 2, (float)2, (float)5.015); SetXY(xdata, ydata, 3, (float)3, (float)6.99);
            SetXY(xdata, ydata, 4, (float)4, (float)9.005);

            var model = new LinModel();
            var p = arena.floatVec(2);

            for (int rep = 0; rep < 30; rep++)
            {
                p[0] = (float)0; p[1] = (float)0;
                var info = Optimize.curveFit(in xdata, in ydata, ref model, ref p);
                AssertSolved(info);
                AssertClose(p[0], (float)2, (float)0.01);
                AssertClose(p[1], (float)1, (float)0.01);
            }

            arena.Dispose();
        }

        static void SetXY(floatN X, floatN Y, int i, float x, float y)
        {
            X[i] = x;
            Y[i] = y;
        }

        static float RelErr2(float a0, float a1, float t0, float t1)
        {
            float dx0 = a0 - t0, dx1 = a1 - t1;
            float num = math.sqrt(dx0 * dx0 + dx1 * dx1);
            float den = math.sqrt(t0 * t0 + t1 * t1);
            return num / den;
        }

        private void AssertSolved(NLSInfo info)
        {
            bool ok = info.Solved;
            if (!ok && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = (float)(int)info.status;
                Fail[2] = (float)0;
                Fail[3] = (float)0;
            }
            Assert.IsTrue(ok);
        }

        private void AssertFinite(float v)
        {
            if (!math.isfinite(v) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = v;
                Fail[2] = (float)0;
                Fail[3] = (float)0;
            }
            Assert.IsTrue(math.isfinite(v));
        }

        private void AssertClose(float a, float b, float precision)
        {
            float diff = math.abs(a - b);
            if (!(diff <= precision) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = a;
                Fail[2] = b;
                Fail[3] = diff;
            }
            Assert.IsTrue(diff <= precision);
        }

        private void AssertLess(float a, float b)
        {
            if (!(a < b) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = a;
                Fail[2] = b;
                Fail[3] = (float)0;
            }
            Assert.IsTrue(a < b);
        }

        private void AssertGreater(float a, float b)
        {
            if (!(a > b) && Fail[0] == (float)0)
            {
                Fail[0] = (float)1;
                Fail[1] = a;
                Fail[2] = b;
                Fail[3] = (float)0;
            }
            Assert.IsTrue(a > b);
        }
    }

    public static Array GetEnums()
    {
        return Enum.GetValues(typeof(TestJob.TestType));
    }

    [TestCaseSource("GetEnums")]
    public void NLSTests(TestJob.TestType type)
    {
        var fail = new NativeArray<float>(4, Allocator.TempJob);
        try
        {
            new TestJob() { Type = type, Fail = fail }.Run();
            if (fail[0] != (float)0)
                Assert.Fail($"got {fail[1]}, expected/limit {fail[2]}, diff/extra {fail[3]}");
        }
        catch (Exception e)
        {
            if (fail[0] != (float)0)
                Assert.Fail($"{type}: got {fail[1]}, expected/limit {fail[2]}, diff/extra {fail[3]} ({e.Message})");
            throw;
        }
        finally
        {
            fail.Dispose();
        }
    }

    // Managed throw-tests: argument validation runs on the main thread (not in a Burst job).

    [Test]
    public void CurveFitThrowsOnDimMismatch()
    {
        var arena = new Arena(Allocator.Persistent);

        var xdata = arena.floatVec(3);
        var ydata = arena.floatVec(4);
        var model = new LinModel();
        var p = arena.floatVec(2);

        Assert.Catch<ArgumentException>(() =>
            Optimize.curveFit(in xdata, in ydata, ref model, ref p));

        arena.Dispose();
    }

